for (int i = 0; i < n_points; i++) {
    // Generate random x in [a, b]
    seed = (lcg_a * seed + c) % m;
    double x = a + range * (static_cast<double>(seed) / m);

    // Generate random y in [0, fmax]
    seed = (lcg_a * seed + c) % m;
    double y = fmax * (static_cast<double>(seed) / m);

    // Check if it's a hit
    double fx = f(x);
    if (y <= fx) {
        hits++;
    }
}

double area = static_cast<double>(hits) / n_points * (b - a) * fmax;
return area;

